let state={step:1,type:'Document',dataset:'Sales Invoice',name:'Sales Invoice',folder:'Sales',layout:'Classic',template:'clean',theme:'Emerald',font:'10',language:'English',hidden:[],tab:'design',dirty:false,required:true,settled:false,join:'AND',filter:true,period:'all',previewCustomer:'Al Noor Trading',calc:'net',dataTab:'links',db:'MongoDB'};
